var mode='uri',dataUri='',mime='',fileName='image';
var tabs=document.getElementById('tabs'),out=document.getElementById('out'),note=document.getElementById('note');
function kb(b){return b<1024?b+' B':b<1048576?(b/1024).toFixed(1)+' KB':(b/1048576).toFixed(2)+' MB';}
function render(){
  if(!dataUri){out.value='';return;}
  var raw=dataUri.slice(dataUri.indexOf(',')+1);
  if(mode==='uri')out.value=dataUri;
  else if(mode==='raw')out.value=raw;
  else if(mode==='css')out.value='background-image: url("'+dataUri+'");\nbackground-size: cover;\nbackground-position: center;';
  else out.value='<img src="'+dataUri+'" alt="'+fileName+'">';
  WT.resize();
}
tabs.addEventListener('click',function(e){
  var b=e.target.closest('button'); if(!b)return;
  [].forEach.call(tabs.querySelectorAll('button'),function(x){x.classList.remove('active');});
  b.classList.add('active'); mode=b.getAttribute('data-m'); render();
});
document.getElementById('file').addEventListener('change',function(){
  var f=this.files&&this.files[0]; if(!f)return;
  if(!/^image\//.test(f.type)){note.textContent='That file is not an image.';return;}
  if(f.size>3145728){note.textContent='That image is over 3 MB. Base64 would be enormous, so compress or resize it first.';}
  fileName=f.name; mime=f.type;
  var r=new FileReader();
  r.onload=function(e){
    dataUri=e.target.result;
    var enc=dataUri.length;
    document.getElementById('s1').textContent=kb(f.size);
    document.getElementById('s2').textContent=kb(enc);
    document.getElementById('s3').textContent='+'+Math.round((enc/f.size-1)*100)+'%';
    document.getElementById('stats').style.display='';
    document.getElementById('prev').src=dataUri;
    document.getElementById('pw').style.display='';
    document.getElementById('copy').disabled=false;
    document.getElementById('clear').disabled=false;
    if(f.size<=3145728)note.textContent='Encoded '+fileName+' as '+mime+'. Pick the format you need above.';
    render();
  };
  r.readAsDataURL(f);
});
document.getElementById('copy').addEventListener('click',function(){
  var ok=WT.copy(out.value);
  note.textContent=ok?'Copied to clipboard.':'Copy failed, select the text instead.';
});
document.getElementById('clear').addEventListener('click',function(){
  dataUri='';out.value='';document.getElementById('stats').style.display='none';
  document.getElementById('pw').style.display='none';
  document.getElementById('copy').disabled=true;this.disabled=true;
  document.getElementById('file').value='';
  note.textContent='Pick an image. The encoding happens on your device, nothing is uploaded.';
  WT.resize();
});
